"""Run from an installed Evorto checkout. Uses two fresh, private Compose projects."""
import argparse
import contextlib
import json
import os
import pathlib
import signal
import socket
import subprocess
import tempfile
import time
import uuid

args = argparse.ArgumentParser(description=__doc__)
args.add_argument("--expect-leak", action="store_true", help="Verify the pre-repair failure")
args.add_argument("--bun-wrapper", action="store_true", help="Send SIGTERM to the Bun package wrapper")
options = args.parse_args()
root = pathlib.Path.cwd()
project = "evo102-" + uuid.uuid4().hex[:12]
lease_script = root / "helpers/testing/with-docker-project-lease.sh"
assert lease_script.is_file() and (root / "node_modules/.bin/playwright").is_file()

def run(env, *cmd, check=True):
    return subprocess.run(cmd, env=env, cwd=root, text=True, capture_output=True, check=check, timeout=30)

def inventory(env):
    label = "label=com.docker.compose.project=" + env["COMPOSE_PROJECT_NAME"]
    return [sorted(run(env, "docker", *cmd, "-q", "--filter", label).stdout.splitlines())
            for cmd in [["ps", "-a"], ["network", "ls"], ["volume", "ls"]]]

def lease(env):
    return run(env, "bash", str(lease_script), "evo102-probe", "--", "true", check=False).returncode

def wait_for(probe, deadline=30):
    until = time.monotonic() + deadline
    while time.monotonic() < until:
        if probe():
            return
        time.sleep(.1)
    raise TimeoutError(probe)

def sql(env, statement):
    return run(env, "docker", "compose", "exec", "-T", "db", "psql", "-U", "postgres", "-tAc", statement)

with tempfile.TemporaryDirectory(prefix=project + "-") as tmp:
    directory = pathlib.Path(tmp)
    with contextlib.ExitStack() as allocation:
        sockets = [allocation.enter_context(socket.socket()) for _ in range(4)]
        for sock in sockets:
            sock.bind(("127.0.0.1", 0))
        ports = [sock.getsockname()[1] for sock in sockets]

    def make_env(name, app, db):
        return {**os.environ, "PATH": str(root / "node_modules/.bin") + os.pathsep + os.environ["PATH"],
                "COMPOSE_FILE": str(directory / "compose.yml"), "COMPOSE_PROJECT_NAME": name,
                "APP_HOST_PORT": str(app), "POSTGRES_HOST_PORT": str(db), "BASE_URL": f"http://127.0.0.1:{app}",
                "NO_WEBSERVER": "false", "E2E_USE_DOCKER_STACK": "true", "E2E_SELECTED_PROJECTS": "local-chrome-baseline",
                "ASTRA_REPO": str(root), "ASTRA_MARKER": str(directory / "in-global-setup")}
    owned = make_env(project, *ports[:2])
    preserved = make_env(project + "-preserved", *ports[2:])
    (directory / "compose.yml").write_text("""
services:
  db:
    image: postgres:17-alpine
    environment:
      POSTGRES_PASSWORD: REDACTED
    ports:
      - "127.0.0.1:\${POSTGRES_HOST_PORT}:5432"
    volumes:
      - fixture:/var/lib/postgresql/data
  ready:
    image: axllent/mailpit@sha256:94f6b70c1436defae6799d9ac7ff0eeff9540465b842026d5cdb018f1c0234ea
    ports:
      - "127.0.0.1:\${APP_HOST_PORT}:8025"
volumes:
  fixture:
""")
    (directory / "playwright.config.cjs").write_text("""
const path = require('node:path');
const base = require(path.join(process.env.ASTRA_REPO, 'playwright.config.ts')).default;
module.exports = {testDir:__dirname, outputDir:path.join(__dirname,'out'), testMatch:'fixture.spec.cjs',
  globalSetup:require.resolve('./setup.cjs'), reporter:'dot',
